const maxED = 8192;
const dec = new TextDecoder(), enc = s => new TextEncoder().encode(s);
const pad4 = n => -n & 3;

// ------------------------- 通用工具 -------------------------
const hexToBytes = s => { const r = new Uint8Array(s.length / 2); for (let i = 0; i < r.length; i++) r[i] = parseInt(s.substr(i * 2, 2), 16); return r; };
const b64encode = s => btoa(unescape(encodeURIComponent(s)));
const b64decode = s => decodeURIComponent(escape(atob(s)));
// base64url -> bytes（edgetunnel early-data 用）
const base64urlToBytes = s => {
  const pad = s.length % 4 === 0 ? '' : '='.repeat(4 - s.length % 4);
  const b64 = s.replace(/-/g, '+').replace(/_/g, '/') + pad;
  const bin = atob(b64), out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
};

const UUID_REGEX = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/;
async function MD5MD5(文本) {
  const m = new Uint8Array(await crypto.subtle.digest('MD5', enc(String(文本))));
  let h = ''; for (let i = 0; i < m.length; i++) h += m[i].toString(16).padStart(2, '0');
  return h;
}

// ------------------------- 网络 / DNS -------------------------
async function resolveIP(h) {
  if (/^\d+\.\d+\.\d+\.\d+$/.test(h)) return h;
  try {
    const r = await fetch(`https://cloudflare-dns.com/dns-query?name=${encodeURIComponent(h)}&type=A`,
      { headers: { Accept: 'application/dns-json' } });
    const j = await r.json();
    const a = (j.Answer || []).find(x => x.type === 1);
    return a ? a.data : null;
  } catch { return null; }
}
const dial = async (h, p) => { const s = connect({ hostname: h, port: p }); await s.opened; return s; };

// ------------------------- VLESS 解析 -------------------------
const u16 = (b, o = 0) => (b[o] << 8) | b[o + 1];
const addr = (t, b) => t === 3 ? dec.decode(b) : t === 1 ? b.join('.') : t === 4 ? `[${Array.from({ length: 8 }, (_, i) => u16(b, i * 2).toString(16)).join(':')}]` : '';
const parseAddr = (b, o, t) => { const l = t === 3 ? b[o++] : t === 1 ? 4 : t === 4 ? 16 : 0; return l && o + l <= b.length ? { addrBytes: b.subarray(o, o + l), dataOffset: o + l } : null; };
function vlessOf(c, idB) {
  for (let i = 0; i < 16; i++) if (c[i + 1] !== idB[i]) return null;
  const o = 19 + c[17];
  const cmd = c[18 + c[17]];            // command: 1=TCP, 3=MUX/UDP
  const t = c[o + 2] === 1 ? 1 : c[o + 2] + 1;  // addrtype: 1/2/3 -> 1/3/4
  const a = parseAddr(c, o + 3, t);
  return a ? { cmd, addrType: t, ...a, port: u16(c, o) } : null;
}
const relay = async (rd, send, close) => { try { for (;;) { const { done, value } = await rd.read(); if (done) break; value?.byteLength && send(value); } } catch {} finally { rd.releaseLock(); close(); } };
const safeClose = (...a) => a.forEach(x => { try { x?.close?.(); } catch {} });

