const xudpResp = (host, port, payload) => { const a = encodeAddr(host), ml = 7 + a.length, buf = new Uint8Array(2 + ml + 2 + payload.length); [buf[0], buf[1], buf[4], buf[5], buf[6], buf[7], buf[8]] = [ml >> 8, ml & 0xff, 2, 1, 2, port >> 8, port & 0xff]; buf.set(a, 9); const pOff = 2 + ml; [buf[pOff], buf[pOff + 1]] = [payload.length >> 8, payload.length & 0xff]; buf.set(payload, pOff + 2); return buf; };

// ---------------- TURN UDP relay (RFC5766) ----------------
async function turnUDP({ host, port, user, pass }, sendWs) {
  let sock = null, closed = false;
  const perms = new Set(), sess = new Map(), reverse = {};
  const close = () => { closed = true; safeClose(sock); };
  try {
    sock = await dial(host, port);
    const w = sock.writable.getWriter(), r = sock.readable.getReader();
    const auth = await turnAuth(w, r, 17, { user, pass }); if (!auth) { close(); return null; }
    const { aa, sign } = auth; let buf = auth.ex;
    (async () => {
      while (!closed) {
        const [m, nx] = await readStun(r, buf); buf = nx; if (!m) break;
        if (m.type === MT.DI && m.attrs[AT.PEER] && m.attrs[AT.DATA]) {
          const [ip, pt] = parseXorPeer(m.attrs[AT.PEER]), s = reverse[`${ip}:${pt}`];
          sendWs(xudpResp(s?.host ?? ip, s?.port ?? pt, m.attrs[AT.DATA]));
        }
      }
    })();
    const ensurePerm = ip => { if (perms.has(ip)) return; perms.add(ip); sign(stunMsg(MT.PQ, tid(), [stunAttr(AT.PEER, xorPeer(ip, 0)), ...aa])).then(m => w.write(m)); };
    const sendUDP = (ip, port, data) => w.write(stunMsg(MT.SI, tid(), [stunAttr(AT.PEER, xorPeer(ip, port)), stunAttr(AT.DATA, data)]));
    const getIP = (h, p) => {
      const k = `${h}:${p}`, c = sess.get(k); if (c) return c.ip;
      const ft = fakeIPType(h);
      if (ft) for (const s of sess.values()) if (s.port === p && s.isV6 === (ft === 6)) { const ns = { ip: s.ip, host: h, port: p, isV6: s.isV6 }; sess.set(k, ns); reverse[`${s.ip}:${p}`] = ns; return s.ip; }
      return null;
    };
    const resolveAsync = async (h, p, k) => { const ip = await resolveIP(h); if (ip) { const s = { ip, host: h, port: p, isV6: ip.includes(':') }; sess.set(k, s); reverse[`${ip}:${p}`] = s; } };
    const processXUDP = data => {
      while (data.length >= 6) {
        const f = parseXUDP(data); if (!f) break;
        if (f.network === 2 && f.payload?.length && f.host) {
          const k = `${f.host}:${f.port}`, ip = getIP(f.host, f.port);
          ip ? (ensurePerm(ip), sendUDP(ip, f.port, f.payload)) : sess.has(k) || resolveAsync(f.host, f.port, k);
        }
        data = data.subarray(f.totalLen);
      }
    };
    return { processXUDP, close };
  } catch { close(); return null; }
}

// ---------------- WebSocket VLESS 代理 ----------------
async function handleWS(request, userID, url, turn) {
  const [client, server] = Object.values(new WebSocketPair());
  server.accept();
  const ed = request.headers.get('sec-websocket-protocol');
  const idB = hexToBytes(String(userID).replaceAll('-', ''));
  let w = null, sock = null, udp = null, chain = Promise.resolve();
  const close = () => { udp?.close(); safeClose(sock, server); };
  const send = d => { try { server.send(d); } catch {} };
  const process = async chunk => {
    if (w) return w.write(chunk);
    if (udp) return udp.processXUDP(chunk);
    const ack = () => send(new Uint8Array([chunk[0], 0]));
    const v = vlessOf(chunk, idB); if (!v) return close(); ack();
    // UDP (cmd=3) 必须走 TURN relay
    if (v.cmd === 3) {
      if (!turn) return close();
      udp = await turnUDP(turn, send); if (!udp) return close();
      const ud = chunk.subarray(v.dataOffset); ud.length && udp.processXUDP(ud);
      return;
    }
    // TCP (cmd=1)
    const host = addr(v.addrType, v.addrBytes), payload = chunk.subarray(v.dataOffset);
    if (turn) {
      const ip = v.addrType === 1 ? host : await resolveIP(host); if (!ip) return close();
      sock = await turnConn(turn, ip, v.port).catch(() => null); if (!sock) return close();
    } else {
      try { sock = await dial(host, v.port); } catch { return close(); }
    }
    w = sock.writable.getWriter();
    payload.byteLength && await w.write(payload);
    relay(sock.readable.getReader(), send, close);
  };
  if (ed?.length && ed.length <= maxED) {
    // early-data: sec-websocket-protocol 携带 base64url 编码的首包
    try { chain = chain.then(() => process(base64urlToBytes(ed))).catch(close); } catch {}
  }
  server.addEventListener('message', e => {
    const data = e.data;
    let buf;
    if (data instanceof ArrayBuffer) buf = new Uint8Array(data);
    else if (ArrayBuffer.isView(data)) buf = new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
    else if (typeof data === 'string') buf = base64urlToBytes(data);
    else return;
    chain = chain.then(() => process(buf)).catch(close);
  });
  server.addEventListener('close', close);
  server.addEventListener('error', close);
  return new Response(null, { status: 101, webSocket: client, headers: ed ? { 'sec-websocket-protocol': ed } : {} });
}

// ======================================================================
//  订阅 / 节点链接生成
// ======================================================================
function makeLink(uuid, host, pathEnc, name, udp) {
  const base = `vless://${uuid}@${host}:443/?type=ws&security=tls&encryption=none&host=${encodeURIComponent(host)}&sni=${host}&fp=chrome&path=${encodeURIComponent(pathEnc)}`;
  return `${base}${udp ? '&packetEncoding=xudp' : ''}#${encodeURIComponent(name)}`;
}
function turnPathOf(node) {
  const [hp, , , cred] = node;
  return `/turn://${cred ? cred + '@' : ''}${hp}?ed=2560`;
}
function buildSubscription(uuid, host, cfg) {
  const links = [];
  const subName = (cfg && cfg.SUBNAME) || 'edgetunnel';
  // 主节点：TCP 直连
  links.push(makeLink(uuid, host, '/', subName, false));
  // TURN 节点：优先 ALL + 无认证，按上限截取
  const nodes = (TURN_NODES || DEFAULT_TURN_NODES);
  let limit = (cfg && cfg.SUBLimit) || 20;
  const pool = nodes;
  const ordered = pool.slice().sort((a, b) => (a[2] ? 0 : 1) - (b[2] ? 0 : 1));
  const picked = [];
  for (const n of ordered) {
    if (picked.length >= limit) break;
    if (n[1] === 'UDP' && n[3]) continue; // UDP 认证节点不稳定，跳过
    picked.push(n);
  }
  for (const n of picked) {
    links.push(makeLink(uuid, host, turnPathOf(n), `TURN-${n[2] || 'NA'}`, true));
  }
  return links.join('\n');
}

// ======================================================================
//  TURN 节点轮询（可达性 + 认证模式 + 时延）
// ======================================================================
async function pollTurnNode(n, timeout = 5000) {
  const [hp, type, cc, cred] = n;
  const [h, p] = hp.split(':');
  const t0 = Date.now();
  let s = null;
  try {
    s = connect({ hostname: h, port: +p });
    const opened = await Promise.race([s.opened, new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), timeout))]);
    void opened;
    const w = s.writable.getWriter(), r = s.readable.getReader();
    await w.write(stunMsg(MT.AQ, tid(), [stunAttr(AT.TRANSPORT, new Uint8Array([17, 0, 0, 0]))]));
    const [msg] = await Promise.race([readStun(r), new Promise(res => setTimeout(() => res([null, null]), timeout))]);
    const ms = Date.now() - t0;
    try { w.releaseLock(); r.releaseLock(); s.close(); } catch {}
    if (!msg) return { ...n, ok: false, ms, auth: 'UNKNOWN' };
    if (msg.type === MT.AO) return { ...n, ok: true, ms, auth: 'NO_AUTH' };
    if (msg.type === MT.AE && parseErr(msg.attrs[AT.ERR]) === 401) return { ...n, ok: true, ms, auth: 'CRED' };
    return { ...n, ok: false, ms, auth: 'REJECT' };
  } catch (e) {
    try { safeClose(s); } catch {}
    return { ...n, ok: false, ms: Date.now() - t0, auth: 'FAIL' };
  }
}
async function pollAll(nodes, limit = 50) {
  const targets = nodes.slice(0, limit);
  const results = [];
  const CONC = 12;
  let idx = 0;
  const worker = async () => { while (idx < targets.length) { const i = idx++; results.push(await pollTurnNode(targets[i])); } };
  await Promise.all(Array.from({ length: Math.min(CONC, targets.length) }, worker));
  return results;
}

// ======================================================================
//  面板后端
// ======================================================================
function json(data, status = 200) { return new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json;charset=utf-8' } }); }
async function authOK(request, 管理员密码, 加密秘钥) {
  const c = request.headers.get('Cookie') || '';
  const m = c.split(';').find(x => x.trim().startsWith('auth='));
  if (!m) return false;
  const expect = (await MD5MD5(管理员密码 + 加密秘钥)).slice(0, 24);
  return m.split('=')[1] === expect;
}
async function loadNodes(env) {
  if (TURN_NODES) return TURN_NODES;
  if (env && env.KV && typeof env.KV.get === 'function') {
    try { const s = await env.KV.get('turn_nodes.json'); if (s) { const arr = JSON.parse(s); if (Array.isArray(arr) && arr.length) { TURN_NODES = arr; return TURN_NODES; } } } catch {}
  }
  TURN_NODES = DEFAULT_TURN_NODES;
  return TURN_NODES;
}
async function readConfig(env, host, userID) {
  const 默认 = {
    HOST: host, UUID: userID, PATH: '/', ALPN: '', Fingerprint: 'chrome',
    SUBNAME: 'edgetunnel', SUBLimit: 20, UDP: true, XUDP: true
  };
  if (config_JSON) return config_JSON;
  if (env && env.KV && typeof env.KV.get === 'function') {
    try { const s = await env.KV.get('config.json'); if (s) { config_JSON = Object.assign(默认, JSON.parse(s)); return config_JSON; } } catch {}
  }
  config_JSON = 默认;
  return config_JSON;
}

// ======================================================================
//  主入口
// ======================================================================
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;
    const upgrade = (request.headers.get('Upgrade') || '').toLowerCase();
    const 管理员密码 = env.ADMIN || env.admin || env.PASSWORD || env.password || env.pswd || env.TOKEN || env.KEY || env.UUID || env.uuid;
    const 加密秘钥 = env.KEY || 'edgetunnel-turn-default-key';
    const envUUID = env.UUID || env.uuid;
    let userID;
    if (envUUID && UUID_REGEX.test(envUUID)) userID = envUUID.toLowerCase();
    else {
      const m = await MD5MD5((管理员密码 || 'noadmin') + 加密秘钥);
      userID = [m.slice(0, 8), m.slice(8, 12), '4' + m.slice(13, 16), '8' + m.slice(17, 20), m.slice(20)].join('-');
    }
    const hosts = env.HOST ? (await Promise.all(String(env.HOST).split(',').map(s => s.trim()))).map(h => h.toLowerCase().replace(/^https?:\/\//, '').split('/')[0].split(':')[0]) : [url.hostname];
    const host = hosts[0];

    // ---------- WebSocket VLESS 代理 ----------
    if (upgrade === 'websocket') {
      if (!管理员密码) return new Response('未设置 ADMIN，代理未启用', { status: 403 });
      const turn = getTurn(url.pathname + url.search);
      return await handleWS(request, userID, url, turn);
    }

    // ---------- HTTP 路由 ----------
    // 订阅
    if (path === '/sub' || path === '/sub/') {
      const cfg = await readConfig(env, host, userID);
      const content = buildSubscription(userID, host, cfg);
      const b64 = b64encode(content);
      const headers = new Headers({ 'Content-Type': 'text/plain;charset=utf-8' });
      headers.set('Profile-Update-Interval', String((cfg.SUBUpdateTime || 3) * 60 * 60));
      headers.set('Profile-web-page-url', url.origin + '/');
      if (!(request.headers.get('User-Agent') || '').includes('mozilla')) headers.set('Content-Disposition', `attachment; filename*=utf-8''${encodeURIComponent(cfg.SUBNAME)}`);
      return new Response(b64, { headers });
    }
    // 明文节点文本
    if (path === '/nodes' || path === '/nodes/') {
      const cfg = await readConfig(env, host, userID);
      return new Response(buildSubscription(userID, host, cfg), { headers: { 'Content-Type': 'text/plain;charset=utf-8' } });
    }

    // ---------- 管理面板 / 登录 ----------
    if (path === '/login') {
      if (!管理员密码) return json({ ok: false, msg: '未配置 ADMIN' });
      if (request.method === 'POST') {
        const body = await request.text();
        const pwd = new URLSearchParams(body).get('password');
        if (String(pwd) === String(管理员密码).replace(/[\r\n]/g, '')) {
          const token = await MD5MD5(管理员密码 + 加密秘钥);
          const resp = json({ ok: true });
          resp.headers.set('Set-Cookie', `auth=${token.slice(0, 24)}; Path=/; Max-Age=86400; HttpOnly; Secure; SameSite=Lax`);
          return resp;
        }
        return json({ ok: false, msg: '密码错误' }, 401);
      }
      return new Response(LOGIN_HTML, { headers: { 'Content-Type': 'text/html;charset=utf-8' } });
    }

    // API 需登录
    const authed = await authOK(request, 管理员密码 || '', 加密秘钥);
    if (path.startsWith('/api/')) {
      if (!管理员密码) return json({ ok: false, msg: '未配置 ADMIN，请先在环境变量中设置' }, 403);
      if (!authed) return json({ ok: false, msg: '未登录' }, 401);

      if (path === '/api/config') {
        if (request.method === 'GET') { const cfg = await readConfig(env, host, userID); return json(cfg); }
        if (request.method === 'POST') {
          const body = JSON.parse(await request.text());
          const cfg = await readConfig(env, host, userID);
          config_JSON = Object.assign(cfg, body);
          if (env.KV && typeof env.KV.put === 'function') await env.KV.put('config.json', JSON.stringify(config_JSON, null, 2));
          return json({ ok: true, config: config_JSON });
        }
      }
      if (path === '/api/turn') {
        if (request.method === 'GET') { const nodes = await loadNodes(env); return json({ total: nodes.length, nodes }); }
        if (request.method === 'POST') {
          const body = await request.json().catch(() => ({}));
          const nodes = await loadNodes(env);
          if (body.reset) {
            TURN_NODES = DEFAULT_TURN_NODES;
            if (env.KV && typeof env.KV.delete === 'function') await env.KV.delete('turn_nodes.json');
            return json({ ok: true, total: TURN_NODES.length });
          }
          if (Array.isArray(body.nodes)) {
            TURN_NODES = body.nodes;
            if (env.KV && typeof env.KV.put === 'function') await env.KV.put('turn_nodes.json', JSON.stringify(TURN_NODES, null, 2));
            return json({ ok: true, total: TURN_NODES.length });
          }
          if (body.node) {
            const n = body.node;
            if (!n[0] || !n[0].includes(':')) return json({ ok: false, msg: '格式应为 host:port' }, 400);
            nodes.push([n[0], n[1] || 'ALL', n[2] || '', n[3] || '']);
            TURN_NODES = nodes;
            if (env.KV && typeof env.KV.put === 'function') await env.KV.put('turn_nodes.json', JSON.stringify(TURN_NODES, null, 2));
            return json({ ok: true, total: TURN_NODES.length });
          }
          if (body.remove) {
            TURN_NODES = nodes.filter(n => n[0] !== body.remove);
            if (env.KV && typeof env.KV.put === 'function') await env.KV.put('turn_nodes.json', JSON.stringify(TURN_NODES, null, 2));
            return json({ ok: true, total: TURN_NODES.length });
          }
          return json({ ok: false, msg: '未知操作' }, 400);
        }
      }
      if (path === '/api/turn/poll') {
        const nodes = await loadNodes(env);
        const body = await request.json().catch(() => ({}));
        const limit = body.limit || 50;
        const results = await pollAll(nodes, limit);
        return json({ ok: true, results });
      }
      if (path === '/api/nodes') {
        const cfg = await readConfig(env, host, userID);
        return json({ ok: true, content: buildSubscription(userID, host, cfg) });
      }
      return json({ ok: false, msg: '未知 API' }, 404);
    }

    // ---------- 面板主页 ----------
    if (path === '/' || path === '') {
      const cfg = await readConfig(env, host, userID);
      return new Response(PANEL_HTML(host, authed, cfg, 管理员密码 ? true : false), { headers: { 'Content-Type': 'text/html;charset=utf-8' } });
    }

    return new Response('Not Found', { status: 404 });
  }
};

