// ======================================================================
//  Vue3 + Element Plus 管理面板 (CDN)
// ======================================================================
const PANEL_HTML = (host, authed, cfg, hasAdmin) => `<!DOCTYPE html><html lang="zh"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>edgetunnel · TURN 节点面板</title>
<link rel="stylesheet" href="https://unpkg.com/element-plus@2.9.3/dist/index.css">
<style>
:root{--el-color-primary:#3b82f6}html,body{margin:0;background:#0f172a;color:#e2e8f0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif}
.app{max-width:1080px;margin:0 auto;padding:20px}
.topbar{display:flex;align-items:center;justify-content:space-between;padding:16px 0}
.topbar h1{font-size:20px;margin:0}.topbar .tag{font-size:12px;color:#94a3b8}
.card{background:#1e293b;border:1px solid #2b3a50;border-radius:14px;padding:20px;margin-bottom:16px}
.sec-title{font-size:15px;font-weight:600;margin:0 0 14px;display:flex;align-items:center;gap:8px}
.mono{font-family:'SFMono-Regular',Consolas,monospace;font-size:12px;background:#0f172a;border:1px solid #2b3a50;border-radius:8px;padding:10px;white-space:pre-wrap;word-break:break-all;max-height:260px;overflow:auto;color:#7dd3fc}
.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:10px}
.stat{font-size:12px;color:#94a3b8}.ok{color:#22c55e}.bad{color:#ef4444}.warn{color:#f59e0b}
.el-input__inner,.el-textarea__inner{background:#0f172a!important;color:#e2e8f0!important;border-color:#334155!important}
.el-table{--el-table-bg-color:#1e293b!important;--el-table-tr-bg-color:#1e293b!important;--el-table-header-bg-color:#24344a!important;--el-table-border-color:#2b3a50!important;--el-table-text-color:#e2e8f0!important;--el-table-header-text-color:#94a3b8!important}
</style></head><body>
<div id="app" class="app">
  <div class="topbar"><h1>edgetunnel · TURN 节点面板</h1>
    <span class="tag">{{version}} · 主机 {{cfg.HOST}} · {{hasAdmin ? '已启用' : '未设置ADMIN'}}</span></div>

  <el-alert v-if="!hasAdmin" type="warning" show-icon :closable="false"
    title="未配置 ADMIN 环境变量，代理不会启用。请到 CF 控制台添加变量 ADMIN 后重载。"></el-alert>

  <el-tabs v-model="tab" type="border-card">
    <!-- 配置 -->
    <el-tab-pane label="配置" name="cfg">
      <div class="sec-title">节点配置 <span class="stat">（edgetunnel 风格）</span></div>
      <el-form label-width="110px" label-position="left">
        <div class="row"><el-input v-model="cfg.UUID" placeholder="UUID" style="width:360px"><template #prepend>UUID</template></el-input></div>
        <div class="row"><el-input v-model="cfg.HOST" placeholder="HOST" style="width:360px"><template #prepend>HOST</template></el-input>
          <el-input v-model="cfg.PATH" placeholder="/" style="width:140px"><template #prepend>PATH</template></el-input></div>
        <div class="row"><el-input v-model="cfg.ALPN" placeholder="ALPN" style="width:200px"><template #prepend>ALPN</template></el-input>
          <el-input v-model="cfg.Fingerprint" placeholder="chrome" style="width:200px"><template #prepend>fp</template></el-input></div>
        <div class="row"><el-input v-model.number="cfg.SUBLimit" style="width:160px"><template #prepend>订阅节点上限</template></el-input>
          <el-input v-model="cfg.SUBNAME" style="width:200px"><template #prepend>订阅名</template></el-input></div>
        <div class="row">
          <el-switch v-model="cfg.UDP" active-text="UDP" inactive-text="UDP关"></el-switch>
          <el-switch v-model="cfg.XUDP" style="margin-left:20px" active-text="XUDP" inactive-text="XUDP关"></el-switch>
          <el-button type="primary" @click="saveCfg">保存配置</el-button></div>
      </el-form>
    </el-tab-pane>

    <!-- 获取节点 -->
    <el-tab-pane label="获取节点" name="nodes">
      <div class="sec-title">生成节点链接</div>
      <div class="row">
        <el-button type="success" @click="gen('all')">生成订阅(全部)</el-button>
        <el-button @click="gen('turn')">仅 TURN 节点</el-button>
        <el-button @click="copyNodes">复制链接</el-button>
      </div>
      <div class="mono">{{nodeText}}</div>
    </el-tab-pane>

    <!-- TURN 节点轮询 -->
    <el-tab-pane label="TURN 节点" name="turn">
      <div class="sec-title">TURN 节点列表 <span class="stat">共 {{turnTotal}} 个</span>
        <el-button size="small" type="primary" :loading="polling" @click="doPoll">轮询探测</el-button>
        <el-input v-model.number="pollLimit" size="small" style="width:110px"><template #prepend>上限</template></el-input>
      </div>
      <div class="row">
        <el-input v-model="newNode" placeholder="host:port" style="width:180px"></el-input>
        <el-select v-model="newType" style="width:110px"><el-option label="ALL" value="ALL"/><el-option label="UDP" value="UDP"/><el-option label="TCP" value="TCP"/></el-select>
        <el-input v-model="newCred" placeholder="user:pass(空=无认证)" style="width:200px"></el-input>
        <el-input v-model="newCc" placeholder="国家/备注" style="width:120px"></el-input>
        <el-button type="primary" @click="addNode">添加</el-button>
        <el-button @click="resetNodes">恢复内置默认</el-button>
      </div>
      <el-table :data="turnRows" size="small" max-height="420" style="width:100%">
        <el-table-column prop="0" label="host:port" width="170"/>
        <el-table-column prop="1" label="type" width="70"/>
        <el-table-column prop="2" label="国家" width="110"/>
        <el-table-column label="认证" width="120"><template #default="s"><span v-if="s.row[3]">{{s.row[3]}}</span><span v-else class="ok">NO_AUTH</span></template></el-table-column>
        <el-table-column label="状态" width="150"><template #default="s">
          <span v-if="s.row._st===true" class="ok">✓ {{s.row._ms}}ms {{s.row._auth}}</span>
          <span v-else-if="s.row._st===false" class="bad">✗ {{s.row._ms}}ms</span>
          <span v-else class="warn">待测</span></template></el-table-column>
        <el-table-column label="" width="90"><template #default="s"><el-button size="small" type="danger" @click="removeNode(s.row[0])">删除</el-button></template></el-table-column>
      </el-table>
    </el-tab-pane>

    <!-- 订阅 -->
    <el-tab-pane label="订阅" name="sub">
      <div class="sec-title">订阅生成</div>
      <div class="row">
        <el-input :model-value="subUrl" readonly><template #prepend>订阅URL</template></el-input>
        <el-button type="primary" @click="copySub">复制订阅内容</el-button>
      </div>
      <div class="mono">{{subB64}}</div>
    </el-tab-pane>
  </el-tabs>
</div>

<script src="https://unpkg.com/vue@3.4.38/dist/vue.global.prod.js"></script>
<script src="https://unpkg.com/element-plus@2.9.3/dist/index.full.min.js"></script>
<script>
const { createApp, ref, reactive, onMounted } = Vue;
const { ElMessage } = ElementPlus;
const app = createApp({
  setup() {
    const version = '${Version}';
    const hasAdmin = ${hasAdmin ? 'true' : 'false'};
    const tab = ref('cfg');
    const cfg = reactive(${JSON.stringify(cfg || {})});
    const nodeText = ref('');
    const subB64 = ref('');
    const subUrl = ref('');
    const turnRows = ref([]);
    const turnTotal = ref(0);
    const newNode = ref(''), newType = ref('ALL'), newCred = ref(''), newCc = ref('');
    const polling = ref(false);
    const pollLimit = ref(30);

    async function api(p, method, body) {
      const opt = { method, headers: {} };
      if (body) { opt.headers['Content-Type'] = 'application/json'; opt.body = JSON.stringify(body); }
      const r = await fetch(p, opt);
      if (r.status === 401) { location.href = '/login'; throw new Error('未登录'); }
      return r.json();
    }
    async function saveCfg() { const j = await api('/api/config', 'POST', cfg); if (j.ok) { Object.assign(cfg, j.config); ElMessage.success('已保存'); } }
    async function gen(which) {
      const j = await api('/api/nodes', 'GET');
      if (!j.ok) return;
      nodeText.value = which === 'turn' ? j.content.split('\\n').filter(l => l.includes('xudp')).join('\\n') : j.content;
      ElMessage.success('已生成');
    }
    async function copyNodes() { await copy(nodeText.value); }
    async function loadTurn() {
      const j = await api('/api/turn', 'GET');
      if (j.ok) { turnTotal.value = j.total; turnRows.value = j.nodes; }
    }
    async function doPoll() {
      polling.value = true;
      const j = await api('/api/turn/poll', 'POST', { limit: pollLimit.value });
      if (j.ok) {
        const map = {};
        j.results.forEach(r => { map[r[0]] = { _st: r.ok, _ms: r.ms, _auth: r.auth }; });
        turnRows.value = turnRows.value.map(r => Object.assign({}, r, map[r[0]] || {}));
        ElMessage.success('轮询完成: ' + j.results.length + ' 个');
      }
      polling.value = false;
    }
    async function addNode() {
      if (!newNode.value.includes(':')) { ElMessage.warning('格式应为 host:port'); return; }
      const j = await api('/api/turn', 'POST', { node: [newNode.value, newType.value, newCc.value, newCred.value] });
      if (j.ok) { ElMessage.success('已添加'); newNode.value=''; newCred.value=''; newCc.value=''; loadTurn(); }
    }
    async function removeNode(hp) { const j = await api('/api/turn', 'POST', { remove: hp }); if (j.ok) { ElMessage.success('已删除'); loadTurn(); } }
    async function resetNodes() { const j = await api('/api/turn', 'POST', { reset: true }); if (j.ok) { ElMessage.success('已恢复内置默认(' + j.total + ')'); loadTurn(); } }
    async function copy(t) { try { await navigator.clipboard.writeText(t); ElMessage.success('已复制'); } catch { ElMessage.info(t); } }
    async function copySub() { if (!subB64.value) { subB64.value = '// 生成中...'; try { const j = await api('/api/nodes','GET'); subB64.value = btoa(unescape(encodeURIComponent(j.content))); } catch(e){} } await copy(subB64.value); }

    onMounted(async () => {
      await loadTurn();
      subUrl.value = location.origin + '/sub';
      try { const j = await api('/api/nodes', 'GET'); subB64.value = btoa(unescape(encodeURIComponent(j.content))); } catch (e) {}
    });
    return { version, hasAdmin, tab, cfg, nodeText, subB64, subUrl, turnRows, turnTotal, newNode, newType, newCred, newCc, polling, pollLimit, saveCfg, gen, copyNodes, loadTurn, doPoll, addNode, removeNode, resetNodes, copySub };
  }
});
app.use(ElementPlus).mount('#app');
</script>
</body></html>`;
